	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void disabledIntervalAlwaysRequiresNewGeneration(boolean mutate, @TempDir Path directory) throws Exception {
		Path live = directory.resolve("store");
		Path backup = directory.resolve("backup");
		LmdbStore store = open(live, true);
		BackupResult oldFull;
		try {
			add(store, "initial");
			oldFull = full(store, backup);
		} finally {
			store.shutDown();
		}
		store = open(live, false);
		try {
			if (mutate) {
				add(store, "unlogged");
				namespace(store, "urn:unlogged:");
			}
		} finally {
			store.shutDown();
		}
		store = open(live, true);
		try {
			LmdbStore active = store;
			assertThrows(SailException.class, () -> incremental(active, backup, oldFull.getEndTransactionId()));
			BackupResult fresh = full(store, backup);
			assertFalse(generation(oldFull).equals(generation(fresh)));
			if (!mutate) {
				assertEquals(oldFull.getEndTransactionId(), fresh.getEndTransactionId());
			}
			add(store, "logged");
			BackupResult delta = incremental(store, backup, fresh.getEndTransactionId());
			Path restored = store.getBackupService()
					.restore(new PointInTimeRestoreRequest(backup,
							directory.resolve("restore"), delta.getEndTransactionId(), true));
			LmdbStore copy = open(restored, true);
			try (var connection = copy.getConnection()) {
				assertEquals(mutate ? 3 : 2, connection.size());
				if (mutate) {
					assertEquals("urn:unlogged:", connection.getNamespace("ex"));
				}
				assertThrows(SailException.class, () -> incremental(copy, directory.resolve("copy-backup"),
						delta.getEndTransactionId()));
			} finally {
				copy.shutDown();
			}
			deleteTree(fresh.getArtifactPath().getParent());
			assertThrows(SailException.class, () -> active.getBackupService()
					.restore(
							new PointInTimeRestoreRequest(backup, directory.resolve("gap-restore"),
									delta.getEndTransactionId(), false)));
			assertFalse(Files.exists(directory.resolve("gap-restore")));
		} finally {
			store.shutDown();
		}
	}

