	@Test
	void interruptedEnableRepeatsResetInsteadOfRecoveringOldGeneration(@TempDir Path directory) throws Exception {
		AtomicInteger resets = new AtomicInteger();
		assertThrows(IOException.class, () -> LmdbBackupJournalState.open(directory, true, 17L, () -> {
			resets.incrementAndGet();
			Files.writeString(directory.resolve("simulated-ack"), "17");
			throw new IOException("Stopped after resetting acknowledgement, before enabled state");
		}));
		var state = LmdbBackupJournalState.open(directory, true, 17L, () -> resets.incrementAndGet());
		assertEquals(2, resets.get());
		assertTrue(state.enabled());
		assertEquals(-1L, state.firstFullBaseline());
		state.establishBaseline(17L);
		var reopened = LmdbBackupJournalState.open(directory, true, 19L, () -> {
			throw new AssertionError("An enabled restart must preserve its publisher");
		});
		assertEquals(state.generation(), reopened.generation());
		assertEquals(17L, reopened.firstFullBaseline());
	}

