	@Test
	void fullOnlyRestoreRejectsLaterTargetsAndPreservesExistingDestination(@TempDir Path directory) throws Exception {
		LmdbStore store = open(directory.resolve("store"), false);
		Path backup = directory.resolve("backup");
		Path existing = Files.createDirectory(directory.resolve("existing"));
		Path marker = Files.writeString(existing.resolve("important"), "preserve");
		try {
			add(store, "one");
			BackupResult full = full(store, backup);
			add(store, "two");
			assertThrows(SailException.class, () -> store.getBackupService()
					.restore(
							new PointInTimeRestoreRequest(backup, existing, full.getEndTransactionId(), true)));
			assertEquals("preserve", Files.readString(marker));
			Path target = directory.resolve("missing");
			assertThrows(SailException.class, () -> store.getBackupService()
					.restore(
							new PointInTimeRestoreRequest(backup, target, full.getEndTransactionId() + 1, false)));
			assertFalse(Files.exists(target));
			Path empty = Files.createDirectory(directory.resolve("empty"));
			store.getBackupService()
					.restore(new PointInTimeRestoreRequest(backup, empty,
							full.getEndTransactionId(), true));
			assertTrue(Files.isRegularFile(empty.resolve("triples/data.mdb")));
			assertThrows(SailException.class, () -> store.getBackupService()
					.restore(
							new PointInTimeRestoreRequest(backup, directory.resolve("store/subdir"),
									full.getEndTransactionId(), true)));
			assertThrows(SailException.class, () -> store.getBackupService()
					.restore(
							new PointInTimeRestoreRequest(backup, backup.resolve("subdir"),
									full.getEndTransactionId(), true)));
		} finally {
			store.shutDown();
		}
	}

	@Test
	void legacyJournalRemainsRestorableButCannotConsumeNewGeneration(@TempDir Path directory) throws Exception {
		LmdbStore store = open(directory.resolve("store"), true);
		Path backup = directory.resolve("backup");
		try {
			add(store, "base");
			BackupResult full = full(store, backup);
			add(store, "delta");
			long target = incremental(store, backup, full.getEndTransactionId()).getEndTransactionId();
			// Model an existing legacy metadata/journal pair without altering the native snapshot or its checksum.
			Path metadata = full.getArtifactPath().getParent().resolve("metadata.properties");
			Properties properties = readProperties(metadata);
			properties.remove("journalMode");
			properties.remove("journalGeneration");
			writeProperties(metadata, properties);
			assertThrows(SailException.class, () -> store.getBackupService()
					.restore(
							new PointInTimeRestoreRequest(backup, directory.resolve("wrong-generation"), target,
									false)));
			Path log = backup.resolve("txlog").resolve(String.format("txn-%020d.delta.gz", target));
			LmdbBackupDeltaCodec.Journal journal;
			try (InputStream input = new GZIPInputStream(Files.newInputStream(log))) {
				journal = LmdbBackupDeltaCodec.readJournal(input);
			}
			try (OutputStream output = new GZIPOutputStream(Files.newOutputStream(log))) {
				LmdbBackupDeltaCodec.write(output, journal.records(), journal.previousTransactionId());
			}
			Path restored = store.getBackupService()
					.restore(new PointInTimeRestoreRequest(backup,
							directory.resolve("legacy-restore"), target, true));
			LmdbStore copy = open(restored, false);
			try (var connection = copy.getConnection()) {
				assertEquals(2, connection.size());
			} finally {
				copy.shutDown();
			}
		} finally {
			store.shutDown();
		}
	}

